package com.futuresillit.arrays;

public class ArrayExampleOne {
	
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int arr[] = new int[5] ; // size is 5 ; which can store integer type
		
		arr[0] = 10;
		arr[1] = 20;
		arr[2] = 30;
		arr[3] =40;
		arr[4] =50;
		
		System.out.println("data at 2nd index :" + arr[2]);
		System.out.println("data at 3rd index :" + arr[3]);
		
	
	}

}

